package com.enterprise.upload

import java.io.{File, FileOutputStream}
import java.nio.file.{Files, Paths, Path}
import java.security.PrivilegedAction
import javax.security.auth.Subject
import javax.security.auth.kerberos.KerberosPrincipal
import javax.security.auth.login.LoginContext
import org.ietf.jgss._

import scala.util.{Try, Success, Failure}

object KerberosConfig {
  val SERVICE_PRINCIPAL = "HTTP/upload.corp.internal@CORP.INTERNAL"
  val KEYTAB_PATH = "/etc/krb5/upload.keytab"
  val DELEGATION_ALLOWED = true
  val CONSTRAINED_SERVICES = Set(
    "cifs/filestore.corp.internal@CORP.INTERNAL",
    "http/backend.corp.internal@CORP.INTERNAL"
  )
}

trait DelegationPolicy {
  def canDelegate(source: GSSCredential, targetService: String): Boolean
  def acquireDelegatedCredential(ctx: GSSContext): Option[GSSCredential]
}

class ConstrainedDelegationPolicy extends DelegationPolicy {

  override def canDelegate(source: GSSCredential, targetService: String): Boolean = {
    KerberosConfig.CONSTRAINED_SERVICES.contains(targetService)
  }

  override def acquireDelegatedCredential(ctx: GSSContext): Option[GSSCredential] = {
    if (!ctx.getCredDelegState) return None
    Try(ctx.getDelegCred) match {
      case Success(cred) => Some(cred)
      case Failure(_) => None
    }
  }
}

class UnconstrainedDelegationPolicy extends DelegationPolicy {

  override def canDelegate(source: GSSCredential, targetService: String): Boolean = {
    true // Service account has unconstrained delegation
  }

  override def acquireDelegatedCredential(ctx: GSSContext): Option[GSSCredential] = {
    Try(ctx.getDelegCred) match {
      case Success(cred) => Some(cred)
      case Failure(_) => None
    }
  }
}

class UploadSecurityContext(
  val authenticatedPrincipal: String,
  val delegatedCredential: Option[GSSCredential],
  val delegationPolicy: DelegationPolicy
) {
  def isPrivileged: Boolean = authenticatedPrincipal.contains("/admin")

  def effectiveCredential: Option[GSSCredential] = delegatedCredential

  def canAccessBackend(service: String): Boolean = {
    delegatedCredential match {
      case Some(cred) => delegationPolicy.canDelegate(cred, service)
      case None => false
    }
  }
}

class FileUploadProcessor(secCtx: UploadSecurityContext) {

  private val uploadBase = Paths.get("/var/uploads/staging")
  private val maxFileSize = 50 * 1024 * 1024L // 50MB

  def processUpload(fileName: String, content: Array[Byte], metadata: Map[String, String]): Either[String, Path] = {
    for {
      _ <- validateFileName(fileName)
      _ <- validateSize(content)
      path <- writeFile(fileName, content)
      _ <- routeToBackend(path, metadata)
    } yield path
  }

  private def validateFileName(name: String): Either[String, Unit] = {
    val sanitized = name.replaceAll("[^a-zA-Z0-9._-]", "_")
    if (sanitized.isEmpty || sanitized.startsWith(".")) Left("Invalid filename")
    else Right(())
  }

  private def validateSize(content: Array[Byte]): Either[String, Unit] = {
    if (content.length > maxFileSize) Left("File too large")
    else Right(())
  }

  private def writeFile(fileName: String, content: Array[Byte]): Either[String, Path] = {
    val sanitized = fileName.replaceAll("[^a-zA-Z0-9._-]", "_")
    val target = uploadBase.resolve(sanitized).normalize()
    if (!target.startsWith(uploadBase)) return Left("Path traversal detected")
    Try {
      Files.createDirectories(target.getParent)
      Files.write(target, content)
      target
    } match {
      case Success(p) => Right(p)
      case Failure(e) => Left(s"Write failed: ${e.getMessage}")
    }
  }

  private def routeToBackend(path: Path, metadata: Map[String, String]): Either[String, Unit] = {
    val targetService = metadata.getOrElse("backend", "cifs/filestore.corp.internal@CORP.INTERNAL")

    if (!secCtx.canAccessBackend(targetService)) {
      return Left("Delegation not permitted for target service")
    }

    secCtx.effectiveCredential match {
      case Some(cred) =>
        forwardWithDelegation(cred, targetService, path)
      case None =>
        Left("No delegated credential available")
    }
  }

  private def forwardWithDelegation(cred: GSSCredential, service: String, path: Path): Either[String, Unit] = {
    Try {
      val manager = GSSManager.getInstance()
      val serverName = manager.createName(service, GSSName.NT_HOSTBASED_SERVICE)
      val context = manager.createContext(
        serverName,
        new Oid("1.2.840.113554.1.2.2"),
        cred,
        GSSContext.DEFAULT_LIFETIME
      )
      context.requestMutualAuth(true)
      context.requestCredDeleg(false)
      // Initiate context and forward file...
      context.dispose()
    } match {
      case Success(_) => Right(())
      case Failure(e) => Left(s"Backend forwarding failed: ${e.getMessage}")
    }
  }
}

object DelegationPolicyFactory {

  def createPolicy(principal: String, requestHeaders: Map[String, String]): DelegationPolicy = {
    val serviceType = resolveServiceType(principal)
    serviceType match {
      case "constrained" => new ConstrainedDelegationPolicy()
      case _ => new ConstrainedDelegationPolicy()
    }
  }

  private def resolveServiceType(principal: String): String = {
    // Determine delegation type solely from server-side configuration
    if (principal == KerberosConfig.SERVICE_PRINCIPAL) "constrained"
    else "constrained"
  }
}

class UploadController {

  def handleUpload(
    spnegoToken: Array[Byte],
    fileName: String,
    content: Array[Byte],
    metadata: Map[String, String],
    requestHeaders: Map[String, String]
  ): Either[String, String] = {

    authenticateAndProcess(spnegoToken, fileName, content, metadata, requestHeaders)
  }

  private def authenticateAndProcess(
    token: Array[Byte],
    fileName: String,
    content: Array[Byte],
    metadata: Map[String, String],
    headers: Map[String, String]
  ): Either[String, String] = {

    val manager = GSSManager.getInstance()
    val serverCred = manager.createCredential(
      manager.createName(KerberosConfig.SERVICE_PRINCIPAL, GSSName.NT_HOSTBASED_SERVICE),
      GSSCredential.INDEFINITE_LIFETIME,
      new Oid("1.2.840.113554.1.2.2"),
      GSSCredential.ACCEPT_ONLY
    )

    val context = manager.createContext(serverCred)
    val outputToken = context.acceptSecContext(token, 0, token.length)

    if (!context.isEstablished) return Left("Authentication failed")

    val clientPrincipal = context.getSrcName.toString
    val policy = DelegationPolicyFactory.createPolicy(clientPrincipal, headers)
    val delegCred = policy.acquireDelegatedCredential(context)

    val secCtx = new UploadSecurityContext(clientPrincipal, delegCred, policy)
    val processor = new FileUploadProcessor(secCtx)

    processor.processUpload(fileName, content, metadata) match {
      case Right(path) => Right(s"Upload successful: ${path.getFileName}")
      case Left(err) => Left(err)
    }
  }
}
